def highlight_all_matches(scores, weights)
  total = scores.each_with_index.sum { |score, index| score * weights[index] }
  total / scores.length
end

solutionCode:
def highlight_all_matches(scores, weights)
  total = scores.each_with_index.sum { |score, index| score * weights[index] }
  total / weights.sum
end
